#import "ShaderFiles.h"

#import "ShaderFiles.inc"  // generated by build.sh: kShaderFiles[]

NSString *ShaderFileText(NSString *name) {
  for (size_t i = 0; i < sizeof kShaderFiles / sizeof kShaderFiles[0]; i++) {
    if (strcmp(kShaderFiles[i].name, name.UTF8String) != 0) continue;
    NSString *text = [[NSString alloc] initWithBytes:kShaderFiles[i].bytes length:kShaderFiles[i].length encoding:NSUTF8StringEncoding];
    return [text stringByReplacingOccurrencesOfString:@"#pragma once\n" withString:@"\n"];
  }
  return nil;
}
